// Equipos simulados del nodo. Los identificadores tienen que ser los registrados en InfoPonia (IoT · Hardware).
// «base» es el valor normal y «ruido», cuánto varía al azar en cada lectura.
flow.set('sensores', [
    { identificador: 'norte/sectorA/temperatura', base: 24, ruido: 1.5, decimales: 1 },
    { identificador: 'norte/sectorA/humedad', base: 70, ruido: 4, decimales: 0 },
    { identificador: 'norte/sectorA/luz', base: 30000, ruido: 3000, decimales: 0, soloDeDia: true },
    { identificador: 'norte/tanque1/temp-solucion', base: 21, ruido: 0.5, decimales: 1 },
    { identificador: 'norte/tanque1/nivel', nivel: true }
]);
flow.set('actuadores', [
    { identificador: 'norte/sectorA/ventilador', comandos: ['ENCENDER', 'APAGAR', 'FIJAR_NIVEL'], estado: 'apagado' },
    { identificador: 'norte/sectorA/ventana', comandos: ['ABRIR', 'CERRAR', 'FIJAR_POSICION'], estado: 'cerrado' }
]);
flow.set('forzado', {});           // condiciones forzadas desde el panel
flow.set('reloj_ok', true);        // false = simula un reloj sin sincronizar
flow.set('cola', []);              // cola de lecturas sin enviar (D-74, punto 3)
flow.set('en_vuelo', false);
flow.set('espera', 10);            // segundos del próximo reintento
flow.set('modo', 'remoto');
if (!env.get('INFOPONIA_URL') || !env.get('INFOPONIA_TOKEN')) {
    node.warn('Faltan las variables de entorno INFOPONIA_URL o INFOPONIA_TOKEN: el flujo no va a poder enviar.');
    node.status({ fill: 'red', shape: 'ring', text: 'faltan INFOPONIA_URL o INFOPONIA_TOKEN' });
} else {
    node.status({ fill: 'green', shape: 'dot', text: 'configurado' });
}
return [msg, msg];

// Al arrancar: el estado de todos los actuadores (D-74, punto 4).

// Funciones comunes del flujo (se copian en cada nodo que las usa).
function base() {
    const url = env.get('INFOPONIA_URL') || '';
    return url.endsWith('/') ? url : url + '/';
}
function encabezados() {
    return { 'Authorization': 'Bearer ' + (env.get('INFOPONIA_TOKEN') || ''),
             'Content-Type': 'application/json' };
}
function ahoraIso() {
    // ISO 8601 con zona (UTC, «Z») y sin milisegundos: D-74, punto 5.
    return new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
}

const estados = (flow.get('actuadores') || []).map(a => {
    const e = { identificador: a.identificador, estado: a.estado };
    if (flow.get('reloj_ok') !== false) e.informado_en = ahoraIso();
    return e;
});
return { ruta: 'estados', cuerpo: { estados: estados } };

// Anuncio: todos los equipos del nodo y los comandos de cada actuador (mensajes.md, sección 4).
const equipos = [];
for (const s of (flow.get('sensores') || [])) equipos.push({ identificador: s.identificador, clase: 'sensor' });
for (const a of (flow.get('actuadores') || [])) {
    let comandos = a.comandos;
    if ((flow.get('forzado') || {}).ventana_sin_posicion && a.identificador.endsWith('/ventana')) {
        comandos = comandos.filter(c => c !== 'FIJAR_POSICION');
    }
    equipos.push({ identificador: a.identificador, clase: 'actuador', comandos: comandos });
}
return { ruta: 'anuncio', cuerpo: { equipos: equipos } };

// Arma un lote con la lectura actual de cada sensor simulado y lo agrega a la cola.

// Funciones comunes del flujo (se copian en cada nodo que las usa).
function base() {
    const url = env.get('INFOPONIA_URL') || '';
    return url.endsWith('/') ? url : url + '/';
}
function encabezados() {
    return { 'Authorization': 'Bearer ' + (env.get('INFOPONIA_TOKEN') || ''),
             'Content-Type': 'application/json' };
}
function ahoraIso() {
    // ISO 8601 con zona (UTC, «Z») y sin milisegundos: D-74, punto 5.
    return new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
}

const sensores = flow.get('sensores') || [];
const forzado = flow.get('forzado') || {};
const relojOk = flow.get('reloj_ok') !== false;
const hora = new Date().getHours();
const lecturas = [];
for (const s of sensores) {
    let valor;
    if (s.nivel) {
        valor = forzado.nivel_bajo ? 'bajo' : 'normal';
    } else if (forzado[s.identificador] !== undefined) {
        valor = forzado[s.identificador];
    } else {
        valor = s.base + (Math.random() * 2 - 1) * s.ruido;
        if (s.soloDeDia && (hora < 8 || hora >= 18)) valor = Math.random() * 50;
        valor = Number(valor.toFixed(s.decimales));
    }
    const l = { identificador: s.identificador, valor: valor };
    if (relojOk) l.medida_en = ahoraIso();      // sin reloj sincronizado, sin fecha (extensión 3e)
    lecturas.push(l);
}
if (forzado.no_registrado) {
    lecturas.push({ identificador: 'norte/sectorB/co2', valor: 450, medida_en: relojOk ? ahoraIso() : undefined });
}
// Sin reloj sincronizado, las lecturas no se encolan: si el envío falla, se descartan (D-74, punto 5).
msg.lecturas = lecturas;
msg.encolar = relojOk;
return msg;

// Cola de lecturas en orden de medición, acotada a 1 hora (D-74, punto 3).
// Con un lote por minuto, 1 hora son unas 60 × (cantidad de sensores) lecturas.
const MAX = 60 * ((flow.get('sensores') || []).length + 1);
let cola = flow.get('cola') || [];
if (msg.encolar) {
    cola = cola.concat(msg.lecturas);
    if (cola.length > MAX) {
        node.warn('Cola llena: se descartan ' + (cola.length - MAX) + ' lecturas viejas.');
        cola = cola.slice(cola.length - MAX);
    }
    flow.set('cola', cola);
    msg.sin_cola = null;
} else {
    msg.sin_cola = msg.lecturas;   // se intentan una sola vez
}
node.status({ text: 'en cola: ' + cola.length });
return msg;

// Arma el pedido POST lecturas: lo más viejo de la cola, hasta 500 (o el latido si no hay nada).

// Funciones comunes del flujo (se copian en cada nodo que las usa).
function base() {
    const url = env.get('INFOPONIA_URL') || '';
    return url.endsWith('/') ? url : url + '/';
}
function encabezados() {
    return { 'Authorization': 'Bearer ' + (env.get('INFOPONIA_TOKEN') || ''),
             'Content-Type': 'application/json' };
}
function ahoraIso() {
    // ISO 8601 con zona (UTC, «Z») y sin milisegundos: D-74, punto 5.
    return new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
}

if (flow.get('en_vuelo')) { node.status({ text: 'esperando respuesta' }); return null; }
const cola = flow.get('cola') || [];
let lote, deCola;
if (cola.length > 0) {
    lote = cola.slice(0, 500); deCola = lote.length;
} else if (msg.sin_cola && msg.sin_cola.length > 0) {
    lote = msg.sin_cola; deCola = 0;
} else {
    lote = []; deCola = 0;     // latido: mantiene al nodo «en línea»
}
flow.set('en_vuelo', true);
msg.de_cola = deCola;
msg.url = base() + 'lecturas';
msg.method = 'POST';
msg.headers = encabezados();
msg.requestTimeout = 15000;
msg.payload = { lecturas: lote };
node.status({ fill: 'blue', shape: 'dot', text: 'enviando ' + lote.length });
return msg;

// Decide según la respuesta (respuestas_y_errores.md, sección 3, «Qué hace el nodo con cada código»).
// Salida 1: reintentar más tarde (con msg.delay). Salida 2: seguir vaciando la cola. Salida 3: registro.
flow.set('en_vuelo', false);
const codigo = msg.statusCode;
const cola = flow.get('cola') || [];
const sacar = () => flow.set('cola', cola.slice(msg.de_cola));

if (codigo === 200) {
    sacar();
    flow.set('espera', 10);
    const p = msg.payload || {};
    // Reloj: si difiere más de 2 minutos de InfoPonia, se trata como no sincronizado (D-74, punto 5).
    if (p.servidor_en) {
        const dif = Math.abs(Date.now() - Date.parse(p.servidor_en)) / 1000;
        if (dif > 120) { flow.set('reloj_ok', false); node.warn('El reloj difiere ' + Math.round(dif) + ' s de InfoPonia: se manda sin fecha hasta corregirlo.'); }
    }
    const rech = (p.resultados || []).filter(r => r.resultado === 'rechazada');
    node.status({ fill: rech.length ? 'yellow' : 'green', shape: 'dot',
        text: 'aceptadas ' + p.aceptadas + ' · duplicadas ' + p.duplicadas + ' · rechazadas ' + p.rechazadas });
    const salidas = [null, null, null];
    if (rech.length) salidas[2] = { payload: rech, topic: 'lecturas rechazadas (se descartan)' };
    if ((flow.get('cola') || []).length > 0) salidas[1] = { sin_cola: null };
    return salidas;
}
if (codigo === 429 || codigo >= 500 || typeof codigo !== 'number') {
    // Falla pasajera: queda en la cola y se reintenta con espera creciente (10 s → 5 min) o Retry-After.
    let espera = flow.get('espera') || 10;
    const ra = msg.headers && Number(msg.headers['retry-after']);
    const segundos = (codigo === 429 && ra) ? ra : espera;
    flow.set('espera', Math.min(espera * 2, 300));
    node.status({ fill: 'yellow', shape: 'ring', text: 'falla ' + codigo + ': reintento en ' + segundos + ' s' });
    return [{ delay: segundos * 1000, sin_cola: null }, null, { payload: msg.payload, topic: 'falla pasajera ' + codigo }];
}
// 400, 401, 403, 404, 405, 413, 415: no se reintenta (se saca de la cola y se informa).
sacar();
const e = msg.payload || {};
node.status({ fill: 'red', shape: 'dot', text: codigo + ' ' + (e.error || '') });
return [null, null, { payload: e, topic: 'mensaje rechazado ' + codigo + ' (no se reintenta)' }];

// Arma un pedido de estados, modo o anuncio (msg.ruta y msg.cuerpo los pone quien lo dispara).

// Funciones comunes del flujo (se copian en cada nodo que las usa).
function base() {
    const url = env.get('INFOPONIA_URL') || '';
    return url.endsWith('/') ? url : url + '/';
}
function encabezados() {
    return { 'Authorization': 'Bearer ' + (env.get('INFOPONIA_TOKEN') || ''),
             'Content-Type': 'application/json' };
}
function ahoraIso() {
    // ISO 8601 con zona (UTC, «Z») y sin milisegundos: D-74, punto 5.
    return new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
}

msg.url = base() + msg.ruta;
msg.method = 'POST';
msg.headers = encabezados();
msg.requestTimeout = 15000;
msg.payload = msg.cuerpo;
msg.intento = (msg.intento || 0) + 1;
return msg;

// Estados, modo y anuncio: reintento simple de las fallas pasajeras (hasta 5 intentos, espera creciente).
const codigo = msg.statusCode;
if (codigo === 429 || codigo >= 500 || typeof codigo !== 'number') {
    if (msg.intento >= 5) { node.warn(msg.ruta + ': sin respuesta tras 5 intentos, se descarta.'); return [null, null]; }
    const ra = msg.headers && Number(msg.headers['retry-after']);
    msg.delay = (codigo === 429 && ra) ? ra * 1000 : 10000 * Math.pow(2, msg.intento - 1);
    node.status({ fill: 'yellow', shape: 'ring', text: msg.ruta + ': reintento ' + msg.intento });
    return [{ ruta: msg.ruta, cuerpo: msg.cuerpo, intento: msg.intento, delay: msg.delay }, null];
}
node.status({ fill: codigo === 200 ? 'green' : 'red', shape: 'dot', text: msg.ruta + ': ' + codigo });
return [null, { payload: msg.payload, topic: msg.ruta + ' ' + codigo }];

// Botones del panel que fuerzan una condición: msg.payload = { clave: valor } o 'normal' para volver a la normalidad.
if (msg.payload === 'normal') {
    flow.set('forzado', {}); flow.set('reloj_ok', true);
    node.status({ text: 'todo normal' });
    return msg;
}
const f = flow.get('forzado') || {};
for (const k of Object.keys(msg.payload)) {
    if (k === 'reloj_ok') flow.set('reloj_ok', msg.payload[k]);
    else f[k] = msg.payload[k];
}
flow.set('forzado', f);
node.status({ text: Object.keys(msg.payload).join(', ') });
return msg;

// Botones del panel que informan un estado: msg.payload = { identificador, estado }.

// Funciones comunes del flujo (se copian en cada nodo que las usa).
function base() {
    const url = env.get('INFOPONIA_URL') || '';
    return url.endsWith('/') ? url : url + '/';
}
function encabezados() {
    return { 'Authorization': 'Bearer ' + (env.get('INFOPONIA_TOKEN') || ''),
             'Content-Type': 'application/json' };
}
function ahoraIso() {
    // ISO 8601 con zona (UTC, «Z») y sin milisegundos: D-74, punto 5.
    return new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
}

const e = { identificador: msg.payload.identificador, estado: msg.payload.estado };
if (flow.get('reloj_ok') !== false) e.informado_en = ahoraIso();
const acts = flow.get('actuadores') || [];
const a = acts.find(x => x.identificador === e.identificador);
if (a && !['en_linea', 'desconectado', 'en_falla'].includes(e.estado)) { a.estado = e.estado; flow.set('actuadores', acts); }
return { ruta: 'estados', cuerpo: { estados: [e] } };

// Botones del panel que cambian el modo: msg.payload = 'local' o 'remoto'.
flow.set('modo', msg.payload);
return { ruta: 'modo', cuerpo: { modo: msg.payload } };
